const cursor = $('Get Review Cursor').first().json.last_reviewed_at;
const cursorTime = new Date(cursor).getTime();
const items = $json.items || [];
return items
  .filter((s) => {
    const t = new Date(s.updated_at || s.created_at || 0).getTime();
    return t > cursorTime;
  })
  .map((s) => ({ json: s }));

const bySession = {};
for (const item of $input.all()) {
  const row = item.json;
  if (!row || !row.session_id) continue;
  (bySession[row.session_id] ??= []).push(row);
}
const allSessions = $('Filter New Sessions').all().map((i) => i.json);
return allSessions.map((s) => ({
  json: {
    sessionId: s.id,
    turnRows: bySession[s.id] || [],
  },
}));

const rows = $json.turnRows;
const transcript = rows.map((r) => 'User: ' + r.user_message + '\nAmy: ' + r.agent_reply).join('\n');
const toolCallsSummary = rows
  .flatMap((r) => (Array.isArray(r.tool_calls) ? r.tool_calls : []))
  .map((tc) => (tc.tool || '?') + '(' + JSON.stringify(tc.input) + ') -> ' + (typeof tc.output === 'string' ? tc.output.slice(0, 300) : JSON.stringify(tc.output)))
  .join('\n') || '(no tool calls)';
const last = rows[rows.length - 1];
return [{
  json: {
    sessionId: $json.sessionId,
    turnIds: rows.map((r) => r.id),
    transcript,
    toolCallsSummary,
    personaPromptHash: last ? last.persona_prompt_hash : null,
    userCardSnapshot: last ? last.user_card_snapshot : [],
    userCardForAmySnapshot: last ? last.user_card_for_amy_snapshot : [],
    noTraceAvailable: false,
  },
}];

const enriched = $('Build Enriched Transcript').item.json;
return [{
  json: {
    ...enriched,
    personaPromptText: $json.system_prompt || '(persona snapshot missing)',
  },
}];

const messages = $json.items || [];
const transcript = messages.map((m) => (m.peer_id === 'user' ? 'User' : 'Amy') + ': ' + m.content).join('\n');
return [{ json: { transcript } }];

return [{
  json: {
    sessionId: $('Group Turns By Session').item.json.sessionId,
    turnIds: [],
    transcript: $json.transcript,
    toolCallsSummary: '(no tool-call trace recorded for this session)',
    personaPromptText: '(unknown - no persona snapshot recorded for this session)',
    userCardSnapshot: [],
    userCardForAmySnapshot: [],
    noTraceAvailable: true,
  },
}];

// Most sessions in this project's real usage volume are well under the
// budget - this only actually splits pathologically long ones, and never
// mid-turn (splits on the "User:"/"Amy:" line boundaries Format Transcript
// and Build Enriched Transcript both emit).
const CHUNK_CHARS = 12000;
const lines = ($json.transcript || '').split('\n');
const chunks = [];
let current = [];
let currentLen = 0;
for (const line of lines) {
  if (currentLen + line.length > CHUNK_CHARS && current.length) {
    chunks.push(current.join('\n'));
    current = [];
    currentLen = 0;
  }
  current.push(line);
  currentLen += line.length + 1;
}
if (current.length) chunks.push(current.join('\n'));
if (!chunks.length) chunks.push('');

return chunks.map((transcript, chunkIndex) => ({
  json: {
    sessionId: $json.sessionId,
    chunkIndex,
    turnIds: $json.turnIds,
    transcript,
    toolCallsSummary: $json.toolCallsSummary,
    personaPromptText: $json.personaPromptText,
    userCardSnapshot: $json.userCardSnapshot,
    userCardForAmySnapshot: $json.userCardForAmySnapshot,
    noTraceAvailable: $json.noTraceAvailable,
  },
}));

const scoreId = $json.id;
const attributions = $('Execute Judge Subworkflow').item.json.attributions || [];
return attributions.map((a) => ({
  json: {
    reviewScoreId: scoreId,
    type: a.type,
    confidence: typeof a.confidence === 'number' ? a.confidence : 0.5,
    evidence: a.evidence || '',
    suggestedFixArea: a.suggested_fix_area || a.suggestedFixArea || null,
  },
}));

const items = $input.all();
if (!items.length) return [];
const times = items.map((i) => new Date(i.json.updated_at || i.json.created_at || 0).getTime()).filter((t) => !isNaN(t));
if (!times.length) return [];
return [{ json: { maxTime: new Date(Math.max(...times)).toISOString(), sessionsScanned: items.length } }];
